import React from "react";
import { prisma } from "../db";
import { StatsOverview } from "../components/stats-overview";
import { KanbanBoard, type KanbanMatchItem } from "../components/kanban-board";

// Вимикаємо кешування для завжди свіжих даних із бази
export const dynamic = "force-dynamic";

export default async function DashboardPage() {
  // 1. Отримуємо всі оцінені матчі напряму з бази через Prisma
  const matches = await prisma.match.findMany({
    include: {
      vacancy: true,
    },
    orderBy: {
      score: "desc",
    },
  });

  const totalVacancies = await prisma.vacancy.count();

  // 2. Рахуємо бізнес-метрики
  const highScoreMatches = matches.filter((m) => m.score >= 70).length;
  const appliedCount = matches.filter((m) => m.status === "APPLIED").length;
  const averageScore = matches.length
    ? Math.round(matches.reduce((acc, m) => acc + m.score, 0) / matches.length)
    : 0;

  // 3. Агрегуємо аналітику відсутніх скілів (Market Skill Gap)
  const skillCountMap = new Map<string, number>();
  for (const m of matches) {
    for (const skill of m.missingSkills) {
      const normalized = skill.trim();
      if (!normalized) continue;
      skillCountMap.set(normalized, (skillCountMap.get(normalized) || 0) + 1);
    }
  }

  const topMissingSkills = Array.from(skillCountMap.entries())
    .map(([skill, count]) => ({ skill, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);

  const formattedMatches: KanbanMatchItem[] = matches.map((m) => ({
    id: m.id,
    score: m.score,
    status: m.status,
    reason: m.reason,
    matchedSkills: m.matchedSkills,
    missingSkills: m.missingSkills,
    createdAt: m.createdAt,
    vacancy: {
      id: m.vacancy.id,
      title: m.vacancy.title,
      company: m.vacancy.company,
      source: m.vacancy.source,
      url: m.vacancy.url,
      location: m.vacancy.location,
      salary: m.vacancy.salary,
      postedAt: m.vacancy.postedAt,
    },
  }));

  return (
    <div className="space-y-10">
      {/* Метрики та аналітика ринку */}
      <StatsOverview
        totalVacancies={totalVacancies}
        highScoreMatches={highScoreMatches}
        appliedCount={appliedCount}
        averageScore={averageScore}
        topMissingSkills={topMissingSkills}
      />

      {/* Головна Kanban-дошка */}
      <KanbanBoard initialMatches={formattedMatches} />
    </div>
  );
}
